cap={}
for (id,name,icon,group,minAge,sector,rev,gm,wsh,rsh,unit,ticket,req,blurb,eq,ro,xr,names) in S:
    need=gm-0.17
    if wsh+rsh>need: k=need/(wsh+rsh); wsh*=k; rsh*=k
    bd=rev/ticket; wages=rev*0.65*wsh; rent=round(rev*0.65*rsh,-2)
    equip=[]; ec=[0.42,0.42,0.36]
    costs=[rev*0.18,rev*0.12,rev*0.07]  # equipment priced so payback is ~2.5-4 years like the older types
    for i,n in enumerate(eq): equip.append({'id':['a','b','c'][i] if False else n.lower().split()[0]+str(i),'name':n,'cost':round(costs[i],-2),'cap':round(bd*ec[i],1)}|({'starter':1} if i<2 else {}))
    rs=[3,2]; rb=[wages*0.55/3, wages*0.45/2]
    roles=[{'id':'r'+str(i),'name':n,'base':round(rb[i],-2),'cap':round(bd*0.45/rs[i],1),'starter':rs[i]} for i,n in enumerate(ro)]
    risks=[RISK['lawsuit'],RISK['breakin']]+([{'id':'x','label':xr[0],'p':xr[1],'cost':xr[2],'rep':xr[3]}] if xr else [])
    up=[{"id":"marketing","name":"Marketing campaign","cost":round(rev*0.06,-2),"effect":{"demand":0.12},"desc":"+12% demand"},{"id":"efficiency","name":"Efficiency program","cost":round(rev*0.08,-2),"effect":{"margin":0.03},"desc":"+3% margin"},{"id":"insurance","name":"Business insurance","cost":round(rev*0.05,-2),"effect":{"mitigate":0.5},"desc":"halves risk losses"},{"id":"expand","name":"Expansion","cost":round(rev*0.12,-2),"effect":{"demand":0.18,"cap":0.1},"desc":"+18% demand"}]
    T[id]={"kind":"shop","x":True,"name":name,"icon":icon,"group":group,"blurb":blurb,"minAge":minAge,"sector":sector,"fee":round(max(5000,rev*0.05),-3),"ticket":ticket,"cogs":round(1-gm+0.04+0.12*max(0,gm-0.5),2),"rent":rent,"baseDemand":round(bd,1),"unit":unit,"equip":equip,"roles":roles,"req":req,"risks":risks,"upgrades":up,"names":names,"ceo":True}
